            elif strig[j+1].isalpha():
                c += strig[j+1].upper()
            elif strig[j+1].isdigit():
                c += strig[j+1]
        elif strig[j].isalpha():
            c += strig[j+1]
        elif strig[j].isnumeric():
            c += strig[j+1]
        elif strig[j] in ':,':
            c += ' '
    return c
def solution(strig):
    g = ham1(strig)
    kq = ham2(g)
    return kq
