import re
import sys

def normalize_text(s: str) -> str:
    # 1. Loại bỏ ký tự không hợp lệ
    s = re.sub(r"[^a-zA-Z0-9 ,:]", "", s)

    # 2. Tách theo khoảng trắng, dấu phẩy, dấu hai chấm (giữ lại dấu phân cách)
    tokens = re.split(r"(\s|,|:)", s)

    result = []
    for token in tokens:
        if token == "" or token in [" ", ",", ":"]:
            # Giữ nguyên khoảng trắng, dấu phẩy, dấu hai chấm
            result.append(token)
        else:
            # 3. Viết hoa chữ cái đầu, còn lại viết thường
            result.append(token.capitalize())

    # 4. Ghép lại
    return "".join(result)

if __name__ == "__main__":
    text = sys.stdin.read().rstrip("\n")
    print(normalize_text(text))

