import sys
import re

def normalize_text(text: str) -> str:
    # Step 1: Remove invalid characters (keep letters, digits, space, comma, colon)
    cleaned = re.sub(r"[^A-Za-z0-9\s,:]", "", text)

    # Step 2: Collapse multiple spaces into one
    cleaned = re.sub(r"\s+", " ", cleaned)

    # Step 3: Split into tokens using regex that captures delimiters
    tokens = re.split(r"([ ,:])", cleaned)

    result = []
    for token in tokens:
        if token in [" ", ",", ":"]:
            result.append(token)
        elif token:
            result.append(token[0].upper() + token[1:].lower())

    return "".join(result)

# For competitive programming
